@startuml

class Customer {
  + VATnumber : string
  + Name : string
  + PhoneNumber : string
  + Address : string
}

class Package {
  + IdentifierCode : string
  + Weight : float
  + IsUrgent : boolean
}

class DeliveryCenter {
  + Name : string
  + Address : string
}

class Courier {
  + VATnumber : string
  + Name : string
  + PhoneNumber : string
}

Customer "1" -- "*" Package : sends
Customer "1" -- "1" DeliveryCenter : associatedWith
Customer "0..1" -- "0..*" Package : receives
DeliveryCenter "1" -- "*" Package : routesThrough
DeliveryCenter "1" -- "*" Courier : employs
Courier "1" -- "*" Package : assignedTo

@enduml

